import{_ as l,C as e,o as n,c as s,j as i,E as o,a as d,a2 as r}from"./chunks/framework.C21TwvGF.js";const p=JSON.parse('{"title":"3-hafta (Mentor)","description":"","frontmatter":{"title":"3-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"10-sinf (Android)","link":"/mentor/10-sinf-android/"},"n":3,"bob":"I-bob · Android loyihalarini boshqarish va versiya nazorati tizimlari","lessons":[{"g":7,"title":"7-dars: Git bilan versiya nazorati asoslari","lead":"Git bilan versiya nazorati asoslari: Git repository, commit, log, .gitignore","link":"/mentor/10-sinf-android/hafta-03/dars-1","slide":"/slaydlar/10-sinf-android/hafta-03/dars-1.html","test":"/slaydlar/10-sinf-android/hafta-03/dars-1-test.html"},{"g":8,"title":"8-dars: Git bilan ishlash amaliyoti (Tarmoqlar va Konfliktlar)","lead":">>>>>> feature-api","link":"/mentor/10-sinf-android/hafta-03/dars-2","slide":"/slaydlar/10-sinf-android/hafta-03/dars-2.html","test":"/slaydlar/10-sinf-android/hafta-03/dars-2-test.html"},{"g":9,"title":"9-dars: GitHub’da loyihalar yaratish va boshqarish","lead":"GitHub’da loyihalar yaratish va boshqarish: remote repozitoriy, push, pull, issues, README","link":"/mentor/10-sinf-android/hafta-03/dars-3","slide":"/slaydlar/10-sinf-android/hafta-03/dars-3.html","test":"/slaydlar/10-sinf-android/hafta-03/dars-3-test.html"}],"test":"/slaydlar/10-sinf-android/hafta-03/hafta-test.html"}},"headers":[],"relativePath":"mentor/10-sinf-android/hafta-03/index.md","filePath":"mentor/10-sinf-android/hafta-03/index.md"}'),h={name:"mentor/10-sinf-android/hafta-03/index.md"},c={class:"blk"},g={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},m={class:"blk"},u={id:"baholash-mezoni",tabindex:"-1"};function b(y,a,f,v,q,k){const t=e("Icon");return n(),s("div",null,[i("div",c,[i("h2",g,[o(t,{name:"house"}),a[0]||(a[0]=d(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=r('<p>Mazkur haftada o&#39;tilgan darslar bo&#39;yicha mustaqil bajarish uchun topshiriqlar to&#39;plami. Har bir vazifa 25–30 daqiqaga mo&#39;ljallangan.</p><hr><h2 id="_7-dars-git-bilan-versiya-nazorati-asoslari" tabindex="-1">7-dars: Git bilan versiya nazorati asoslari <a class="header-anchor" href="#_7-dars-git-bilan-versiya-nazorati-asoslari" aria-label="Permalink to &quot;7-dars: Git bilan versiya nazorati asoslari&quot;">​</a></h2><ol><li>Kompyuteringiz terminalida <code>git config --list</code> buyrug&#39;ini ishga tushiring va ismingiz hamda pochtangiz to&#39;g&#39;ri sozlanganini tasdiqlang.</li><li>Yangi papka ochib, <code>git init</code> orqali ombor yarating.</li><li>Loyihada <code>.gitignore</code> faylini ochib, Android uchun eng zarur qoidalarni kiriting: <ul><li><code>.gradle/</code>, <code>build/</code>, <code>app/build/</code></li><li><code>local.properties</code></li><li><code>*.apk</code>, <code>*.aab</code></li></ul></li><li>Kamida 3 ta turli fayl yaratib, ketma-ket 3 ta ma&#39;noli commitni (<code>feat: ...</code>, <code>fix: ...</code>, <code>docs: ...</code>) amalga oshiring va <code>git log --oneline</code> buyrug&#39;i natijasini ko&#39;ring.</li></ol><hr><h2 id="_8-dars-git-bilan-ishlash-amaliyoti-tarmoqlar-va-konfliktlar" tabindex="-1">8-dars: Git bilan ishlash amaliyoti (Tarmoqlar va Konfliktlar) <a class="header-anchor" href="#_8-dars-git-bilan-ishlash-amaliyoti-tarmoqlar-va-konfliktlar" aria-label="Permalink to &quot;8-dars: Git bilan ishlash amaliyoti (Tarmoqlar va Konfliktlar)&quot;">​</a></h2><ol><li>Loyihangizda <code>feature-settings</code> nomli yangi branch oching (<code>git switch -c feature-settings</code>).</li><li>Yangi branchda <code>AppSettings.kt</code> faylini yarating va unga boshlang&#39;ich sozlamalarni yozib commit qiling.</li><li>Asosiy <code>main</code> tarmog&#39;iga qaytib (<code>git switch main</code>), o&#39;zgarishlarni <code>git merge feature-settings</code> buyrug&#39;i bilan birlashtiring. So&#39;ngra eski branchni <code>git branch -d feature-settings</code> orqali o&#39;chiring.</li><li>Bitta fayl ichida sun&#39;iy to&#39;qnashuv (Merge Conflict) hosil qiling, uni qo&#39;lda to&#39;g&#39;rilab, to&#39;qnashuv belgilarini o&#39;chirib, muvaffaqiyatli merge commitini amalga oshiring.</li></ol><hr><h2 id="_9-dars-github-da-loyihalar-yaratish-va-boshqarish" tabindex="-1">9-dars: GitHub’da loyihalar yaratish va boshqarish <a class="header-anchor" href="#_9-dars-github-da-loyihalar-yaratish-va-boshqarish" aria-label="Permalink to &quot;9-dars: GitHub’da loyihalar yaratish va boshqarish&quot;">​</a></h2><ol><li>O&#39;zingizning shaxsiy GitHub akkauntingizda yangi Public repozitoriy yarating.</li><li>Lokal kompyuteringizdagi Android loyihasini masofaviy GitHub repozitoriyasiga ulang (<code>git remote add origin ...</code>) va barcha commitlarni <code>git push -u origin main</code> orqali yuklang.</li><li>Loyihangiz uchun Markdown formatida chiroyli va tushunarli <code>README.md</code> faylini yozing: <ul><li>Loyiha nomi va vazifasi;</li><li>Ishlatilgan kutubxonalar va texnologiyalar;</li><li>Qanday o&#39;rnatish va ishga tushirish bo&#39;yicha qo&#39;llanma.</li></ul></li><li>Repozitoriyda 2 ta yangi &quot;Issue&quot; oching: biri rejadagi funksiya haqida, ikkinchisi xatolik haqida. Ulardan birini commit xabarida <code>fixes #...</code> deb yozish orqali avtomatik yoping.</li></ol><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><h3 id="baholash-mezonlari-jami-100-ball" tabindex="-1">Baholash mezonlari (Jami 100 ball) <a class="header-anchor" href="#baholash-mezonlari-jami-100-ball" aria-label="Permalink to &quot;Baholash mezonlari (Jami 100 ball)&quot;">​</a></h3><ul><li><strong>7-dars vazifasi (30 ball):</strong> Git sozlamalari, 3 ta maydon (Working dir, Staging area, Repo) tushunchasi, Android uchun to&#39;g&#39;ri <code>.gitignore</code> tuzilishi va commitlar intizomi.</li><li><strong>8-dars vazifasi (35 ball):</strong> Yangi branch ochish, branchlar orasida o&#39;tish, toza merge qilish va eng muhimi — Merge Conflict (to&#39;qnashuv)ni qo&#39;lda xatosiz hal qila olish ko&#39;nikmasi.</li><li><strong>9-dars vazifasi (35 ball):</strong> GitHub&#39;da Public repo ochish, remote&#39;ga xatosiz push qilish, chiroyli <code>README.md</code> hujjati va Issues vositasidan maqsadli foydalanish.</li></ul><h3 id="eslatma" tabindex="-1">Eslatma <a class="header-anchor" href="#eslatma" aria-label="Permalink to &quot;Eslatma&quot;">​</a></h3><ul><li>O&#39;quvchilar <code>local.properties</code> va <code>build/</code> kabi og&#39;ir fayllarni GitHub&#39;ga chiqarib yubormaganliklarini tekshiring. Repozitoriy faqat toza manba kodlaridan iborat bo&#39;lishi shart.</li></ul>',16))]),i("div",m,[i("h2",u,[o(t,{name:"list-checks"}),a[3]||(a[3]=d(" Baholash mezoni ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=r('<p><strong>Mavzular:</strong></p><ol><li>Git bilan versiya nazorati asoslari: Gitning vazifasi, 3 holat (Working Dir, Staging Area, Repo), <code>git init</code>, <code>add</code>, <code>commit</code>, <code>log</code>, <code>.gitignore</code></li><li>Git bilan ishlash amaliyoti: <code>git diff</code>, <code>git branch</code>, <code>switch</code>, <code>merge</code>, Merge Conflicts va ularni hal etish, <code>git stash</code>, <code>git revert</code></li><li>GitHub’da loyihalar yaratish va boshqarish: Remote repozitoriy, <code>push</code>, <code>pull</code>, Public vs Private, <code>README.md</code>, Issues, Android Studio integratsiyasi</li></ol><hr><h2 id="baholash-mezonlari" tabindex="-1">Baholash mezonlari <a class="header-anchor" href="#baholash-mezonlari" aria-label="Permalink to &quot;Baholash mezonlari&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Tavsif</th><th>Maks. ball</th></tr></thead><tbody><tr><td><strong>Git Asoslari va .gitignore</strong></td><td>Git arxitekturasini tushunish, terminal buyruqlarini to&#39;g&#39;ri ishlatish, Android Studio uchun mos <code>.gitignore</code> tuza olish va ma&#39;noli commitlar yozish</td><td>30 ball</td></tr><tr><td><strong>Tarmoqlar va Konfliktlarni Yechish</strong></td><td>Alohida branch&#39;da mustaqil ishlash, <code>git merge</code> orqali birlashtirish va yuzaga kelgan to&#39;qnashuvlarni (Merge Conflict) qo&#39;lda to&#39;g&#39;ri bartaraf etish</td><td>35 ball</td></tr><tr><td><strong>GitHub va Masofaviy Hamkorlik</strong></td><td>Remote repozitoriy ulash, <code>git push/pull</code> jarayonlari, professional <code>README.md</code> yozish va Issues bilan ishlay olish</td><td>35 ball</td></tr><tr><td><strong>JAMI</strong></td><td></td><td><strong>100 ball</strong></td></tr></tbody></table><hr><h2 id="o-quvchilar-natijalari-jadvali" tabindex="-1">O&#39;quvchilar natijalari jadvali <a class="header-anchor" href="#o-quvchilar-natijalari-jadvali" aria-label="Permalink to &quot;O&#39;quvchilar natijalari jadvali&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№</th><th>O&#39;quvchi F.I.Sh.</th><th>Git &amp; .gitignore (30)</th><th>Branch &amp; Conflict (35)</th><th>GitHub &amp; README (35)</th><th>Jami ball (100)</th><th>Izoh</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>8</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>9</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>10</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>11</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>12</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="mentor-qaydlari-va-tahlil" tabindex="-1">Mentor qaydlari va tahlil <a class="header-anchor" href="#mentor-qaydlari-va-tahlil" aria-label="Permalink to &quot;Mentor qaydlari va tahlil&quot;">​</a></h2><ul><li><strong>Darsdagi asosiy qiyinchiliklar:</strong> O&#39;quvchilar boshida <code>git commit</code> qilishdan oldin <code>git add</code> qilishni unutishadi yoki commit xabariga bir so&#39;z yozish bilan cheklanishadi. Ularga professional jamoalarda commit xabarlari qoidasi qat&#39;iy ekanini uqtirish zarur.</li><li><strong>Konfliktlardan qo&#39;rqmaslik:</strong> Ko&#39;pchilik o&#39;quvchilar <code>CONFLICT</code> so&#39;zini ko&#39;rganda vahimaga tushadi. Konflikt bu dasturiy buzilish emas, balki tabiiy jarayon ekani va uni har bir dasturchi har kuni bir necha bor yechishi kerakligini jonli misollarda ko&#39;rsatib bering.</li></ul>',11))])])}const _=l(h,[["render",b]]);export{p as __pageData,_ as default};
